-- =============================================================================
-- Restaurant Management System — Seed Data (dev/demo)
-- Menu imported from the house price list (listino). Re-runnable: fixed UUIDs +
-- ON CONFLICT DO NOTHING.
-- UUID prefixes by entity: 1=tables, 2=categories, 3=menu_items,
--   4=reservations, 5=orders, 6=order_items, 9=ingredients, b0=floor_maps
-- =============================================================================

-- FLOOR MAP + TABLES: the real house layout, traced from the paper map
-- (TAVOLI.pdf). Generated by scripts/gen-floor-map-sala.py — edit there, not here.
-- Tables that were crossed out on paper are not created.
on conflict (id) do nothing;

on conflict (id) do nothing;

-- CATEGORIES (from the listino 'categoria', with Pizze/Bruschette split out) --
on conflict (id) do nothing;

-- MENU ITEMS ------------------------------------------------------------------
on conflict (id) do nothing;

-- The Coperto row above is not a browsable item: it is the cover charge, and
-- the app generates it per check from the guest count. Flagged separately so
-- the 217-row insert above stays a straight dump of the listino.
update menu_items set is_coperto = true
 where id = '30000000-0000-0000-0000-000000000091';

-- INGREDIENTS (parsed from the listino 'ingredienti'; powers the 86 board) ----
on conflict (id) do nothing;

-- MENU ITEM ⇄ INGREDIENT LINKS -----------------------------------------------
on conflict do nothing;

-- STAFF: roles + users (PINs: Ava 1234, Harper 1111, Sam 2222) ----------------
set search_path to public, extensions;
   array['manage_tables','manage_reservations','take_orders','checkout_orders','manage_staff',
         'manage_menu','manage_floor','manage_availability','view_stats','manage_printers',
         'override_price','plan_floor','floor_alerts']),
  ('70000000-0000-0000-0000-000000000002', 'Host',
   array['manage_tables','manage_reservations']),
  ('70000000-0000-0000-0000-000000000003', 'Server',
   array['manage_tables','take_orders','checkout_orders']),
  -- also created by the smart_floor migration (same id), for existing DBs
  ('70000000-0000-0000-0000-000000000004', 'Sala Manager',
   array['manage_tables','manage_reservations','plan_floor','floor_alerts'])
on conflict (id) do nothing;

   '70000000-0000-0000-0000-000000000001', crypt('1234', gen_salt('bf'))),
  ('80000000-0000-0000-0000-000000000002', 'Harper',
   '70000000-0000-0000-0000-000000000002', crypt('1111', gen_salt('bf'))),
  ('80000000-0000-0000-0000-000000000003', 'Sam',
   '70000000-0000-0000-0000-000000000003', crypt('2222', gen_salt('bf')))
on conflict (id) do nothing;

-- TABLE TAGS: features used to filter tables (prefix a0) -----------------------
-- is_mandatory: Gestione Sala Smart never seats a party that asked for it
-- at a table without it (the others are preferences)
on conflict (id) do nothing;

-- Gestione Sala Smart: a bill with desserts/coffee is "about to leave". The
-- migration sets this too, but on a reset it runs before the menu exists.
update smart_floor_settings
  set finishing_category_ids = array(select id from categories where name = 'Dolci')
  where finishing_category_ids = '{}';

-- ---------------------------------------------------------------------------
-- Pantry hygiene + demo add-on prices
-- ---------------------------------------------------------------------------
-- The listino's "ingredienti" column split a few beer strengths into the
-- pantry ('5% vol.') plus the bare counts '4' and '6'. Harmless while the
-- pantry only drove the 86 board; now that it is also the POS add-on list they
-- would be offered as pizza toppings. Migrations run BEFORE this file, so the
-- same cleanup has to happen here or a db reset puts them straight back.
-- Narrow on purpose: '^[0-9]' would also take '4 formaggi' and '2 hamburger'.
delete from ingredients where name ~ '^[0-9]+$' or name like '%vol.%';

-- A few realistic add-on prices so the diminishing scale is visible out of the
-- box; everything else stays free until someone prices it in Settings → Menu.
update ingredients set price = 2.00 where name in ('bufala', 'crudo', 'speck', 'gorgonzola', 'brie');
update ingredients set price = 1.50 where name in ('funghi', 'salsiccia', 'tonno', 'grana', 'asiago');
update ingredients set price = 1.00 where name in ('rucola', 'cipolla', 'olive', 'capperi', 'pomodorini');

-- Pizze and bruschette are what actually get customized at the counter.
update menu_items m set allows_variations = true
from categories c
where m.category_id = c.id and lower(c.name) in ('pizze', 'bruschette');
